import { useContext, useState } from 'react';
import AuthContext from '../context/AuthContext';

function Signup() {
  const { register } = useContext(AuthContext);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('user');
  const [error, setError] = useState(null);

  const submit = async (e) => {
    e.preventDefault();
    try {
      await register(name, email, password, role);
      window.location.href = '/';
    } catch (err) {
      console.error('Signup error', err);
      const msg = err?.response?.data?.error || err?.message || 'Signup failed';
      setError(msg);
    }
  };

  return (
    <div className="auth-page">
      <div className="auth-card">
        <h3>Create account</h3>
        <form onSubmit={submit} className="auth-form">
          <label>Name</label>
          <input placeholder="Name" value={name} onChange={(e) => setName(e.target.value)} />

          <label>Email</label>
          <input placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} />

          <label>Password</label>
          <input placeholder="Password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />

          <label>I am a:</label>
          <select value={role} onChange={(e) => setRole(e.target.value)} style={{ width: '100%', padding: '10px', marginBottom: '15px', borderRadius: '4px', border: '1px solid #ddd' }}>
            <option value="user">Candidate (Job Seeker)</option>
            <option value="recruiter">Recruiter (Post Jobs)</option>
          </select>

          <button type="submit" className="btn btn-primary">Signup</button>
          {error && <div className="error">{error}</div>}
        </form>
      </div>
    </div>
  );
}

export default Signup;
